   const item={id:crypto.randomUUID(),pairId:d.pairId,side,src:out.toDataURL('image/png'),name:d.name+' · '+side,width:out.width,height:out.height,ratio:out.width/out.height,sourceId:d.id,mode:S.mode,profile:profile?.[0]||'',cardWidthMm:cardW,cardHeightMm:cardH};
