function startPlacedMove(e){if(e.target.closest?.('.placed-crop-box'))return;const i=Number(e.currentTarget.dataset.placedIndex);let item=S.placedSources[i];if(!item)return;S.activePlacedIndex=i;if(S.cropMode){e.preventDefault();e.stopPropagation();return beginPlacedCrop(e,i);}if(e.target.classList.contains('resize-handle'))return;e.preventDefault();if(e.altKey){item={...item,id:crypto.randomUUID(),x:item.x+4,y:item.y+4};S.placedSources.push(item);drawSheetPreview();}const ix=S.placedSources.indexOf(item),root=$('sheetPreview'),r=root.getBoundingClientRect(),dims=sheetDimensions(),W=dims.width,H=dims.height,sx=e.clientX,sy=e.clientY,ox=item.x,oy=item.y;const move=v=>{item.x=Math.max(0,Math.min(W-item.w,ox+(v.clientX-sx)/r.width*W));item.y=Math.max(0,Math.min(H-item.h,oy+(v.clientY-sy)/r.height*H));snapPlaced(item,ix);const el=root.querySelector('[data-placed-index="'+ix+'"]');if(el){el.style.left=item.x/W*100+'%';el.style.top=item.y/H*100+'%';}};const stop=()=>{snapPlaced(item,ix);window.removeEventListener('pointermove',move);S.activePlacedIndex=ix;drawSheetPreview();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop,{once:true});}
