  const items=sheet.items.filter(c=>c.side===side&&(S.sheetContent==='both'||S.sheetContent===side)&&(S.printFormat==='duplex'||S.printFormat===side));
  if(!items.length&&!((sheet.sourceItems||(sheetIndex===0?S.placedSources:[])).length&&side==='front'))continue;
  const page=document.createElement('div');page.className='print-page';page.style.cssText='width:'+W+'mm;height:'+H+'mm';
  if(side==='front')(sheet.sourceItems||(sheetIndex===0?S.placedSources:[])).forEach(item=>{const el=document.createElement('div');el.className='print-card';Object.assign(el.style,{left:item.x+'mm',top:item.y+'mm',width:item.w+'mm',height:item.h+'mm'});const im=document.createElement('img');im.src=item.src;im.style.objectFit='contain';el.append(im);page.append(el);});
